import SoraFoundation
import SoraUIKit
import UIKit
import XCTest
@testable import SoraPassport

@MainActor
final class NodeSelectionScreenFlowTests: XCTestCase {
    private var views = [NodeSelectionView]()
    override func tearDown(){views = [];super.tearDown()}
    private func node(_ name:String)->ChainNodeModel { ChainNodeModel(url:URL(string:"wss://\(name.lowercased()).example/rpc")!,name:name,apikey:nil) }
    private func chain(_ nodes:Set<ChainNodeModel> = [],custom:Set<ChainNodeModel>? = nil,selected:ChainNodeModel? = nil)->ChainModel { ChainModel(chainId:SoraNodeConnectionPolicy.mainnetGenesis,name:"SORA",nodes:nodes,addressPrefix:69,icon:nil,selectedNode:selected,customNodes:custom,iosMinAppVersion:nil) }
    private func make()->(NodesPresenter,NodeSelectionView,NodeSelectionInteractor,NodeSelectionRoutes) { let p = NodesPresenter(), v = NodeSelectionView(), i = NodeSelectionInteractor(chain:chain()), r = NodeSelectionRoutes(); p.view = v;p.interactor = i;p.wireframe = r;views.append(v);return(p,v,i,r) }
    private func settle() async { try? await Task.sleep(nanoseconds:25_000_000) }
    private func descendants<T:UIView>(_ type:T.Type,_ root:UIView)->[T] { ((root as? T).map{[$0]} ?? [])+root.subviews.flatMap{descendants(type,$0)} }
    private func model(_ names:[String],delegate:NodesCellDelegate? = nil)->NodesViewModel { NodesViewModel(nodesModels:names.map{NodeViewModel(node:node($0),isSelected:false,isCustom:true)},header:"Custom nodes",delegate:delegate) }
    func testSetupRequestsTheNodeCatalogOnce(){let(p,_,i,_) = make();p.setup();XCTAssertEqual(i.setups,1)}
    func testDefaultNodesAreSortedByDisplayedName() async {let(p,v,_,_) = make();p.didReceive(chain:chain([node("Zulu"),node("Alpha")]));await settle();XCTAssertEqual(v.models.first?.models.nodesModels.map{$0.node.name},["Alpha","Zulu"])}
    func testCustomNodesHaveTheirOwnSortedSection() async {let(p,v,_,_) = make();p.didReceive(chain:chain([node("Default")],custom:[node("Two"),node("One")]));await settle();XCTAssertEqual(v.models.count,2);XCTAssertEqual(v.models.last?.models.nodesModels.map{$0.node.name},["One","Two"]);XCTAssertTrue(v.models.last!.models.nodesModels.allSatisfy(\.isCustom))}
    func testAnEmptyCustomCatalogDoesNotAddAnEmptySection() async {let(p,v,_,_) = make();p.didReceive(chain:chain([],custom:[]));await settle();XCTAssertEqual(v.models.count,1);XCTAssertTrue(v.models[0].models.nodesModels.isEmpty)}
    func testSelectedDefaultNodeIsMarkedExactlyOnce() async {let(p,v,_,_) = make();let a = node("Alpha");p.didReceive(chain:chain([a,node("Beta")],selected:a));await settle();XCTAssertEqual(v.models[0].models.nodesModels.filter(\.isSelected).map(\.node),[a])}
    func testSelectedCustomNodeIsMarkedInItsOwnSection() async {let(p,v,_,_) = make();let a = node("Custom");p.didReceive(chain:chain([node("Default")],custom:[a],selected:a));await settle();XCTAssertEqual(v.models.flatMap{$0.models.nodesModels}.filter(\.isSelected).map(\.node),[a])}
    func testCatalogPublicationOccursOnMainThread() async {let(p,v,_,_) = make();let value = chain();await withCheckedContinuation{ continuation in DispatchQueue.global().async { p.didReceive(chain:value);continuation.resume() } };await settle();XCTAssertEqual(v.mainThread,[true])}
    func testAddActionUsesTheCurrentChainAndPresenterController(){let(p,v,i,r) = make();i.chain = chain([node("A")]);p.onAction(.add);XCTAssertTrue(r.controller === v.controller);XCTAssertEqual(r.chain?.chainId,i.chain.chainId);XCTAssertEqual(r.calls,1)}
    func testEditActionCarriesTheExactChosenNode(){let(p,_,_,r) = make();let a = node("Custom");p.onAction(.edit(node:a));guard case .edit(let received) = r.action else {return XCTFail("Missing edit route")};XCTAssertEqual(received,a)}
    func testAddButtonRoutesOnlyOnce(){let(p,_,_,r) = make();p.buttonTapped();XCTAssertEqual(r.calls,1);guard case .add = r.action else {return XCTFail("Missing add route")}}
    func testCustomNodeCompletionRefreshesTheVisibleCatalog() async {let(p,v,_,r) = make();p.onAction(.add);r.completion?(chain([],custom:[node("Saved")]));await settle();XCTAssertEqual(v.models.last?.models.nodesModels.first?.node.name,"Saved")}
    func testMissingViewDoesNotOpenCustomNodeEditor(){let(p,_,_,r) = make();p.view = nil;p.onAction(.add);XCTAssertEqual(r.calls,0)}
    func testRestartDispatchesRootNavigationOnMainThread() async {let(p,_,_,r) = make();await withCheckedContinuation{continuation in DispatchQueue.global().async{p.restart();continuation.resume()}};await settle();XCTAssertEqual(r.rootThreads,[true])}
    func testCopyUsesTheCompleteNodeEndpoint(){let(p,_,_,_) = make();let saved = UIPasteboard.general.items;defer{UIPasteboard.general.items = saved};let a = node("Copy");p.onAction(.copy(node:a));XCTAssertEqual(UIPasteboard.general.string,a.url.absoluteString)}
    func testSelectRequiresConfirmationBeforeChangingNodes(){let(p,v,i,_) = make();p.onAction(.select(node:node("Other")));XCTAssertTrue(i.selected.isEmpty);XCTAssertEqual((v.recording.shown.last as? UIAlertController)?.actions.count,2)}
    func testRemoveRequiresConfirmationBeforeDeletingTheNode(){let(p,v,i,_) = make();p.onAction(.remove(node:node("Custom")));XCTAssertTrue(i.removed.isEmpty);XCTAssertEqual((v.recording.shown.last as? UIAlertController)?.actions.count,2)}
    func testConnectionFailureDisplaysAnExplanation(){let(p,v,_,_) = make();p.showConnectionFailed();let a = v.recording.shown.last as? UIAlertController;XCTAssertFalse(a?.message?.isEmpty ?? true);XCTAssertEqual(a?.actions.count,1)}
    func testNodeCellRendersEveryCatalogEntry(){let c = NodesCell(style:.default,reuseIdentifier:nil);c.bind(viewModel:model(["One","Two"]));XCTAssertEqual(descendants(NodeView.self,c).count,2);XCTAssertTrue(descendants(UILabel.self,c).contains{$0.text == "CUSTOM NODES"})}
    func testNodeCellRebindingRemovesObsoleteRows(){let c = NodesCell(style:.default,reuseIdentifier:nil);c.bind(viewModel:model(["One","Two"]));c.bind(viewModel:model(["Three"]));XCTAssertEqual(descendants(NodeView.self,c).count,1);XCTAssertFalse(descendants(UILabel.self,c).contains{$0.text == "One"})}
    func testNodeCellSelectionReachesOnlyTheCurrentDelegate() throws {let first = NodeSelectionActions(),last = NodeSelectionActions(),c = NodesCell(style:.default,reuseIdentifier:nil);c.bind(viewModel:model(["One"],delegate:first));c.bind(viewModel:model(["Two"],delegate:last));try XCTUnwrap(descendants(NodeView.self,c).first).sendActions(for:.touchUpInside);XCTAssertTrue(first.actions.isEmpty);XCTAssertEqual(last.actions.count,1);guard case .select(let chosen) = last.actions.first else {return XCTFail("Missing selection")};XCTAssertEqual(chosen.name,"Two")}
    func testNodeCellForwardsCopyEditAndRemoveWithExactNode() throws {let d = NodeSelectionActions(),c = NodesCell(style:.default,reuseIdentifier:nil);c.bind(viewModel:model(["One"],delegate:d));let row = try XCTUnwrap(descendants(NodeView.self,c).first),a = node("One");row.onCopy?(a);row.onEdit?(a);row.onRemove?(a);XCTAssertEqual(d.actions.count,3)}
    func testNodeScreenInitialLoadRequestsItsPresenterOnce(){let p = NodeScreenPresenter(),v = NodesViewController();v.presenter = p;v.loadViewIfNeeded();v.loadViewIfNeeded();XCTAssertEqual(p.setups,1)}
    func testNodeScreenRendersTheCatalogSections() throws {let p = NodeScreenPresenter(),v = NodesViewController();v.presenter = p;v.loadViewIfNeeded();v.setup(with:[SectionViewModel(header:NodesHeaderViewModel(title:"Default"),models:model(["One"]))]);let t = try XCTUnwrap(descendants(UITableView.self,v.view).first);XCTAssertEqual(v.tableView(t,numberOfRowsInSection:0),1);XCTAssertEqual(descendants(NodeView.self,v.tableView(t,cellForRowAt:IndexPath(row:0,section:0))).count,1)}
    func testRepeatedCatalogUpdatesDoNotAccumulateLayoutConstraints(){let p = NodeScreenPresenter(),v = NodesViewController();v.presenter = p;v.loadViewIfNeeded();v.setup(with:[]);let count = v.view.constraints.count;for _ in 0..<5 {v.setup(with:[])};XCTAssertEqual(v.view.constraints.count,count)}
    func testNodeScreenAddButtonUsesItsPresenter(){let p = NodeScreenPresenter(),v = NodesViewController();v.presenter = p;v.loadViewIfNeeded();v.editTapped();XCTAssertEqual(p.adds,1)}
    func testNodeScreenAppearanceUsesCompactNavigationTitle(){let p = NodeScreenPresenter(),v = NodesViewController();v.presenter = p;let nav = UINavigationController(rootViewController:v);v.loadViewIfNeeded();v.viewWillAppear(false);XCTAssertEqual(v.navigationItem.largeTitleDisplayMode,.never);v.viewWillDisappear(false);XCTAssertTrue(nav.navigationBar.prefersLargeTitles)}
}
private final class NodeSelectionView:NodesViewProtocol {let recording = NodeSelectionHost();var controller:UIViewController{recording};var isSetup:Bool{true};var loadableContentView:UIView!{recording.view};var shouldDisableInteractionWhenLoading:Bool{false};var models = [SectionViewModel](), mainThread = [Bool]();func setup(with models:[SectionViewModel]){self.models = models;mainThread.append(Thread.isMainThread)};func reloadScreen(with models:[SectionViewModel],updatedIndexs:[Int],isExpanding:Bool){self.models = models};func didStartLoading(){};func didStopLoading(){} }
private final class NodeSelectionHost:UIViewController {var shown = [UIViewController]();override func present(_ viewControllerToPresent:UIViewController,animated:Bool,completion:(()->Void)? = nil){shown.append(viewControllerToPresent);completion?()}}
private final class NodeSelectionInteractor:NodesInteractorInputProtocol {var chain:ChainModel;var setups = 0,selected = [ChainNodeModel](),removed = [ChainNodeModel]();init(chain:ChainModel){self.chain = chain};func setup(){setups += 1};func changeSelectedNode(to node:ChainNodeModel){selected.append(node)};func removeNode(_ node:ChainNodeModel){removed.append(node)}}
private final class NodeSelectionRoutes:NodesWireframeProtocol {var controller:UIViewController?,chain:ChainModel?,action:NodeAction?,completion:((ChainModel)->Void)?,calls = 0,rootThreads = [Bool]();func showRoot(){rootThreads.append(Thread.isMainThread)};func showCustomNode(from controller:UIViewController,chain:ChainModel,action:NodeAction,completion:((ChainModel)->Void)?){self.controller = controller;self.chain = chain;self.action = action;self.completion = completion;calls += 1}}
private final class NodeSelectionActions:NodesCellDelegate {var actions = [NodeAction]();func onAction(_ action:NodeAction){actions.append(action)}}
private final class NodeScreenPresenter:NodesPresenterProtocol,ButtonCellDelegate {var setups = 0,adds = 0;func setup(){setups += 1};func buttonTapped(){adds += 1}}
